-- Hoff Parquet CRM — migration 4: product catalog
-- Run this in the Neon SQL Editor. Safe to re-run — uses ON CONFLICT DO NOTHING
-- so it will never duplicate or overwrite products you've since edited.

create table if not exists products (
  id text primary key,
  name text not null default '',
  category text not null default '',
  wood_species text not null default '',
  unit text not null default 'item',
  price_list_date text not null default '',
  description text not null default '',
  origin text not null default '',
  finish text not null default '',
  grade_notes text not null default '',
  notes text not null default '',
  variations jsonb not null default '[]'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

