insert into products (id, name, category, wood_species, unit, price_list_date, description, origin, finish, grade_notes, notes, variations)
values (
  'seed-riga-oak',
  'Riga Parket Oak Flooring',
  'Engineered Wood Flooring',
  'European Oak',
  'm²',
  '2026-09-01',
  'Riga Parket engineered and solid Oak flooring. Covers three constructions: 2-layer (12/3.2mm and 16/4mm, solid oak wear layer on birch plywood core), 3-layer 17/5mm (5mm oak wear layer on spruce core, oak bottom layer available on request), and Solid 21mm (10mm wear layer, suitable for renovation/resanding). Widths from 150mm to 390mm depending on construction. Grades: Prime, Calm, Lively, Character.',
  'Latvia (Riga Parket)',
  'Unfinished / pre-finish options available as surface services',
  'Prime: selected grade, pin knots <4% of surface, without sapwood. Calm: selected grade, live/replaced knots <14%, without sapwood, neutral brown filler. Lively: sorted traditional grade, knots <23%, dead knots <14%, little cracks allowed, without sapwood, neutral brown filler. Character: traditional grade, knots <29%, dead knots <14%, cracks allowed, without sapwood, neutral brown filler.',
  'Supplier: SIA Riga Parket, Latvia. Source price list dated 1 September 2026, EUR excl. VAT, ex works Latvia. Converted to GBP at EUR/GBP 0.8601 (Bloomberg, 3 September 2026) then marked up 30% for UK client sell price, excl. VAT and delivery. Re-check the live rate before quoting large orders, as FX moves daily. Surcharges not included in variation prices: 21/5mm top layer +€3.00/m², oak bottom layer (3-layer boards) +€9.00/m², pre-finishing from €2.50-€15.00/m² depending on finish, surface services (extra brushed, hard brushed, fillers, saw marks, uneven bevels, hand-scraping, HeartWood butterflies) €2.00-€18.00/m² depending on treatment — apply these as separate line items or add to the unit price when quoting.',
