insert into products (id, name, category, wood_species, unit, price_list_date, description, origin, finish, grade_notes, notes, variations)
values (
  'seed-riga-herringbone',
  'Riga Parket Oak Herringbone',
  'Herringbone',
  'European Oak',
  'm²',
  '2026-09-01',
  'Riga Parket Oak herringbone flooring. 2-layer (12/3mm and 16/4mm, solid oak wear layer on birch plywood core) and 3-layer 17/5mm (oak wear layer on spruce core, oak bottom layer available on request) constructions. Widths 90-150mm, board lengths 600/720/900mm depending on spec. Grades: Prime, Calm, Lively.',
  'Latvia (Riga Parket)',
  'Unfinished / pre-finish options available as surface services',
  'Prime: selected grade, pin knots <4% of surface, without sapwood. Calm: selected grade, live/replaced knots <14%, without sapwood, neutral brown filler. Lively: sorted traditional grade, knots <23%, dead knots <14%, little cracks allowed, without sapwood, neutral brown filler. Character: traditional grade, knots <29%, dead knots <14%, cracks allowed, without sapwood, neutral brown filler.',
