insert into products (id, name, category, wood_species, unit, price_list_date, description, origin, finish, grade_notes, notes, variations)
values (
  'seed-amberwood-install-products',
  'Amber Wood Installation Products',
  'Installation & Labour',
  'N/A',
  'item',
  '2026-09-03',
  'Adhesives, primers and installation consumables supplied by Amber Wood: STAUF 1K and 2K flooring adhesives, STAUF VDP 130 primer (5kg and 10kg), STAUF PU primer VPU 155 S, and a notched trowel. Priced per container/tool as supplied, not per m² — see each variation for pack size and coverage.',
  '',
  '',
  '',
  'Supplier: Amber Wood. Prices in the source sheet are already -40% off Amber Wood''s standard list (our negotiated cost), in EUR. Converted to GBP at EUR/GBP 0.8584 (Xe mid-market, 3 September 2026), then marked up 60% for our sell price, excl. VAT and delivery. Combined multiplier applied to the source EUR price: 0.6 (cost after -40%) x 0.8584 (FX) x 1.6 (+60% markup) = 0.8241. These are priced per pack, not per m² — use the consumption note in each variation''s label to estimate how many packs a job needs. Re-check the live rate before quoting large orders, as FX moves daily.',
  '[{"id": "ec518fa9-ab05-4f2e-96ae-5d3c4aa8e409", "label": "STAUF 1K glue Multilayer, 18.00 kg \u2014 consumption ~1 kg/m\u00b2", "price": 81.91, "costPrice": 51.19}, {"id": "6c7345b9-5fa8-4781-be33-55db2cd01070", "label": "STAUF 2K glue PUK-447 STAUF, 9.8 kg \u2014 consumption ~1 kg/m\u00b2", "price": 42.5, "costPrice": 26.56}, {"id": "efb832d7-e9ab-495f-b585-4f9d174b8f30", "label": "STAUF primer VDP 130, 5.00 kg \u2014 covers 83m\u00b2 if diluted", "price": 32.27, "costPrice": 20.17}, {"id": "0f22b85e-bd61-4b83-b3ed-b9739a66f763", "label": "STAUF primer VDP 130, 10.00 kg \u2014 covers 166m\u00b2 if diluted", "price": 55.84, "costPrice": 34.9}, {"id": "1bca8394-ab24-42f9-b843-c1a654db2f64", "label": "STAUF PU primer VPU 155 S, 5.00 kg \u2014 100g/m\u00b2 per layer", "price": 80.22, "costPrice": 50.14}, {"id": "0a662721-e84a-48c0-a899-b1a72e9340ba", "label": "Notched trowel, 0.9-1.1 kg consumption \u2014 0.1-1.12 kg/m\u00b2", "price": 6.59, "costPrice": 4.12}]'::jsonb
)
on conflict (id) do nothing;

